function runAction(action,el){let id=el.dataset.id,day=Number(el.dataset.day??todayIndex);if(action==='edit-task'){showTaskDetails(id,day);return}if(action==='priority-move'){let ranked=state.days[todayIndex].filter(t=>t.status!=='done').sort((a,b)=>b.priority-a.priority),i=ranked.findIndex(t=>t.id===id),j=i+Number(el.dataset.dir);if(i>=0&&j>=0&&j<ranked.length){let [t]=ranked.splice(i,1);ranked.splice(j,0,t);ranked.forEach((item,n)=>item.priority=n<3?3-n:0);save();toast('Priority order updated')}return}if(action==='workout-details'){openInfo('Workout details',state.days[todayIndex].filter(t=>t.category==='Fitness').map(t=>'<p><strong>'+esc(t.name)+'</strong> · '+(t.duration?durationText(+t.duration):'Duration not set')+'</p>').join('')||'<p>No workout is planned today.</p>');return}if(action==='add-task'){addTaskAt(todayIndex);return}if(action==='add-slot'){addTaskAt(todayIndex,el.dataset.time);return}if(action==='add-priority'){addTaskAt(todayIndex,'','Work');document.getElementById('f-priority').value='1';return}if(action==='add-workout'){addTaskAt(todayIndex,'','Fitness');return}if(action==='add-project-task'){addTaskAt(todayIndex,'','Work');return}if(action==='add-habit'){addTaskAt(todayIndex,'','Habit');document.getElementById('f-repeat').value='true';return}if(action==='daily-stats'){selectPage('Statistics');return}if(action==='work-stats'){selectPage('Statistics');return}if(action==='recovery-detail'){let r=state.recovery[todayIndex]||{sleep:state.trackers.sleep,rest:true,energy:3,score:70,level:'Medium'};openInfo('Recovery score','<div class="factor-list"><p><strong>Sleep</strong><span>'+r.sleep+' hours</span></p><p><strong>Rest</strong><span>'+(r.rest?'Rest day / recovered':'Recovery needed')+'</span></p><p><strong>Energy</strong><span>'+r.energy+' / 5</span></p><p><strong>Workout</strong><span>'+(r.workout?'Workout completed':'No workout recorded')+'</span></p><p class="subtle">Personal tracking only; not a medical assessment.</p></div>');return}if(action==='tracker-open'||action==='tracker-add'){trackerValue(el.dataset.tracker);return}if(action==='edit-work-target'){let v=prompt('Set today·s focused work target in hours:',String(state.workTarget));if(v!==null&&Number(v)>0){state.workTarget=Number(v);save();toast('Work target updated')}return}if(action==='focus'){if(!focusTimer){focusTimer={started:Date.now()};toast('Focus session started')}else{let minutes=Math.max(1,Math.round((Date.now()-focusTimer.started)/60000));let note=prompt('Name this focus session:', 'Deep work');state.focusSessions.push({minutes,ended:Date.now(),note:note||'Focus session'});focusTimer=null;save();toast(minutes+' minute focus session saved')}renderActivePage();return}if(action==='session-detail'){let x=state.focusSessions[Number(el.dataset.session)];if(x)openInfo('Focus session details','<p><strong>'+x.minutes+' minutes</strong> · '+new Date(x.ended).toLocaleString()+'</p><p>'+esc(x.note||'Focus session')+'</p>');return}if(action==='start-workout'){if(!workoutTimer){workoutTimer={started:Date.now(),elapsed:0};toast('Workout timer started')}else if(workoutTimer.started){workoutTimer.elapsed+=(Date.now()-workoutTimer.started)/1000;workoutTimer.started=0;toast('Workout paused')}else{workoutTimer.started=Date.now();toast('Workout resumed')}renderActivePage();return}if(action==='complete-workout'){let t=state.days[todayIndex].find(x=>x.category==='Fitness'&&x.status!=='done');if(t)t.status='done';if(workoutTimer){if(workoutTimer.started)workoutTimer.elapsed+=(Date.now()-workoutTimer.started)/1000;workoutTimer=null}save();toast(t?'Workout completed':'Workout session saved');return}if(action==='habit-history'){openInfo('Habit history','<div class="habit-history">'+DAYNAMES.map((d,i)=>'<p><strong>'+d+'</strong><span>'+state.days[i].filter(t=>t.category==='Habit'&&t.status==='done').length+' completed</span></p>').join('')+'</div>');return}if(action==='habit-day'){let di=Number(el.dataset.day),hs=state.days[di].filter(t=>t.category==='Habit');openInfo(DAYNAMES[di]+' habit history',hs.length?hs.map(t=>'<p>'+esc(t.name)+' · '+(t.status==='done'?'Complete':'Not complete')+'</p>').join(''):'<p>No habits planned for this day.</p>');return}if(action==='stats-range'){statsRange=Number(el.dataset.range);renderActivePage();toast('Showing '+el.textContent);return}if(action==='chart-value'){let v=state.days[Number(el.dataset.day)]||[],n=v.filter(t=>t.status==='done').length;openInfo(DAYNAMES[Number(el.dataset.day)]+' exact value','<p><strong>'+n+' of '+v.filter(t=>t.status!=='skipped').length+'</strong> scheduled tasks completed.</p>');return}if(action==='stat-detail'){let cat=el.dataset.stat;let matching=cat==='workouts'?doneCount('Fitness'):cat==='work'?doneCount('Work'):cat==='habits'?doneCount('Habit'):doneCount();openInfo(el.querySelector('.eyebrow').textContent,'<p><strong>'+matching+'</strong> completed items recorded for this week.</p><p class="subtle">The selected '+statsRange+' day view uses saved routine data. Older history is collected as weeks are completed.</p>');return}if(action==='edit-goal'){goalTarget(Number(el.dataset.goal));return}if(action==='settings-open'){state.settingsSection=el.dataset.section;renderActivePage();document.getElementById('settings-detail').scrollIntoView({behavior:'smooth',block:'center'});return}if(action==='settings-routine'){selectPage('Weekly Routine');return}if(action==='save-reminder'){state.settings.reminderTime=document.getElementById('reminder-time').value;save();toast('Reminder settings saved');return}if(action==='theme'){document.body.classList.toggle('dark-theme',el.dataset.theme==='dark');state.settings.theme=el.dataset.theme;save();toast(el.dataset.theme+' appearance selected');return}if(action==='export-data'){let blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='weekwell-data.json';a.click();URL.revokeObjectURL(a.href);toast('Planner data exported');return}if(action==='reset-data'){if(confirm('Reset all tasks, goals, trackers and settings? This cannot be undone.')){localStorage.removeItem(key);state=load();state.trackers={steps:0,water:0,sleep:7};state.focusSessions=[];state.settings={};state.workTarget=4;save();toast('Planner reset')}return}if(action==='close-detail'){closeInfo()}}
function doneCount(category){return allTasks().filter(t=>t.status==='done'&&(!category||t.category===category)).length}
document.getElementById('detail-back').addEventListener('click',e=>{if(e.target.closest('[data-action=close-detail]'))closeInfo()});appPage.addEventListener('click',e=>{let el=e.target.closest('[data-action]');if(e.target.closest('[data-complete]'))return;if(el){runAction(el.dataset.action,el);return}let task=e.target.closest('[data-open-task]');if(task)showTaskDetails(task.dataset.openTask,Number(task.dataset.day))});
appPage.addEventListener('change',e=>{let cb=e.target.closest('[data-complete]');if(cb){let d=Number(cb.dataset.day),t=state.days[d].find(x=>x.id===cb.dataset.complete);if(t){t.status=cb.checked?'done':'open';save();toast(t.status==='done'?'Task completed':'Task reopened')}return}let setting=e.target.dataset.setting;if(setting){state.settings[setting]=e.target.type==='checkbox'?e.target.checked:e.target.value;save();toast('Accessibility settings saved')}});
let priorityDrag=null;appPage.addEventListener('dragstart',e=>{let card=e.target.closest('#priority-list [data-open-task]');if(card){priorityDrag=card.dataset.openTask;e.dataTransfer.setData('text/plain',priorityDrag)}});appPage.addEventListener('dragover',e=>{if(e.target.closest('#priority-list [data-open-task]'))e.preventDefault()});appPage.addEventListener('drop',e=>{let target=e.target.closest('#priority-list [data-open-task]');if(!target||!priorityDrag)return;e.preventDefault();let list=state.days[todayIndex],a=list.findIndex(t=>t.id===priorityDrag),b=list.findIndex(t=>t.id===target.dataset.openTask);if(a>=0&&b>=0){let [t]=list.splice(a,1);list.splice(b,0,t);save();toast('Priority order updated')}priorityDrag=null});
document.getElementById('days').addEventListener('click',e=>{let dayCard=e.target.closest('.day'),dayHead=e.target.closest('.day-head');if(e.target.closest('#routine-edit'))return;if(dayHead&&dayCard){let i=Number(dayCard.dataset.day);expandedDays[i]=!expandedDays[i];render();return}let tcard=e.target.closest('.task');if(tcard&&!e.target.closest('button')&&!e.target.matches('.check')){showTaskDetails(tcard.dataset.id,Number(tcard.dataset.day));return}if(dayCard&&!e.target.closest('.task')&&!e.target.closest('button')){let i=Number(dayCard.dataset.day);expandedDays[i]=!expandedDays[i];render()}});
document.getElementById('routine-edit').onclick=()=>{routineEdit=!routineEdit;render();toast(routineEdit?'Routine editing enabled':'Routine updated')};
let detailBack=document.getElementById('detail-back');detailBack.addEventListener('click',e=>{if(e.target===detailBack)closeInfo()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeInfo();if(typeof profileMenu!=='undefined'){profileMenu.hidden=true;profileButton.setAttribute('aria-expanded','false')}}});setInterval(updateTimers,1000);

const loadingScreen=document.getElementById('loading-screen'),loadingCaption=document.getElementById('loading-caption'),wordmarkFill=document.getElementById('wordmark-fill');let loadingStart=Date.now();const loadingLines=['quiet the noise.','gathering your week.','making room for what matters.'];const loadTicker=setInterval(()=>{const amount=Math.min(100,(Date.now()-loadingStart)/5400*100);wordmarkFill.setAttribute('width',String(amount*7));loadingCaption.textContent=loadingLines[Math.min(2,Math.floor(amount/33.34))];if(amount>=100){clearInterval(loadTicker);document.body.classList.add('app-started');selectPage('Weekly Routine');loadingScreen.classList.add('loading-exit');setTimeout(()=>{loadingScreen.hidden=true;loadingScreen.classList.remove('loading-exit')},matchMedia('(prefers-reduced-motion: reduce)').matches?0:850)}},45);const app=document.querySelector('.app'),routine=document.getElementById('routine-page');app.hidden=false;app.style.display='flex';try{render();selectPage('Weekly Routine')}catch(error){console.error('Weekly Routine startup failed:',error);routine.hidden=false;appPage.hidden=true;routine.innerHTML='<section class="panel" role="alert"><h2>Weekly Routine could not open</h2><p>Reload the page to try again. If this continues, clear this app’s saved browser data.</p><a class="btn primary" href="/">Reload planner</a></section>'}